fn put(out:[*]u8,at:usize,x:f64)void{const bits:u64=@bitCast(x);for(0..8)|i|out[at+i]=@truncate(bits>>@intCast(i*8));}
export fn gram_schmidt(v:[*]const i64,n:usize,out:[*]u8,cap:usize)i64{if(n<2 or n>18)return -1;const r=v[0];const d=v[1];if(r<1 or r>4 or d<r or d>4 or n!=2+@as(usize,@intCast(r*d)))return -1;var a=[_] [4]f64{.{0} ** 4} ** 4;var q=[_] [4]f64{.{0} ** 4} ** 4;for(0..@intCast(r))|i|{for(0..@intCast(d))|j|{const z=v[2+i*@as(usize,@intCast(d))+j];if(z < -1000 or z>1000 or (j<i and z!=0) or (j==i and (z<100 or z>1000)))return -1;a[i][j]=@as(f64,@floatFromInt(z))/1000.0;}}const bytes=@as(usize,@intCast(r*d*8));if(cap<bytes)return -2;for(0..@intCast(r))|k|{var p=[_]f64{0} ** 4;for(0..k)|i|{var dot:f64=0;var norm:f64=0;for(0..@intCast(d))|j|{dot+=a[k][j]*q[i][j];norm+=q[i][j]*q[i][j];}const f=dot/norm;for(0..@intCast(d))|j|{p[j]+=q[i][j]*f;}}for(0..@intCast(d))|j|{q[k][j]=a[k][j]-p[j];}}for(0..@intCast(r))|i|{for(0..@intCast(d))|j|{put(out,(i*@as(usize,@intCast(d))+j)*8,q[i][j]);}}return @intCast(bytes);}
